import"./chunk-2NFLSA4Y.js";var i={lenses:{theory:{concept:"[[A lens is a transparent body, usually of glass, bounded by two curved (usually spherical) surfaces; it refracts light and can form images.]]"},section:{types:{title:"Converging and diverging lenses",text:"A converging lens is thicker in the middle and has a positive focal length. It bends parallel rays toward a focus. A diverging lens is thinner in the middle and has a negative focal length; parallel rays spread out as if they came from a virtual focus."},rays:{title:"Three useful rays",text:"A ray parallel to the axis leaves a converging lens through its far focus (or, for a diverging lens, as if it came from the near focus). A ray through the optical centre continues straight on. A third ray, aimed at the near focus, leaves parallel to the axis; the simulation draws the first two, which are enough to find the image. Where the outgoing rays meet is the image; dashed backward extensions locate a virtual image."},images:{title:"Real and virtual images",text:"[[A real image forms where refracted rays actually meet and can be caught on a screen.]] For a converging lens, an object beyond the focal point makes a real, inverted image. Inside the focal point, the rays leave diverging: their backward extensions meet in a virtual, upright, enlarged image. A diverging lens makes a virtual, upright, reduced image for a real object."},focus:{title:"The focal point",text:"[[The focal length is the distance from the lens to its principal focus.]] If an object is exactly at the focal point of a converging lens, the outgoing rays are parallel and the image is infinitely far away. A shorter focal length means a more powerful lens."},uses:{title:"Lenses in everyday life",text:"Eyes, cameras, magnifying glasses, microscopes and telescopes all use lenses. A camera lens forms a real image on its sensor. A magnifying glass places the object inside its focal length to produce an enlarged virtual image. Spectacles use lenses to help focus light on the retina."},check:{title:"Check your understanding",text:"What kind of image does a converging lens make when the object is inside its focal length? (Virtual, upright and enlarged.) What happens at the focal point? (The rays leave parallel.) Which lens makes a reduced upright virtual image for a real object? (A diverging lens.) Try the settings and follow the rays."}},formula:{lens:"Thin-lens equation, using signed distances",magnification:"Magnification: image height divided by object height",power:"Lens power (the displayed value is in dioptres, 1/m)"},assumption:{paraxial:"Only paraxial rays close to the optical axis are modelled; the thin-lens equation ignores spherical aberration.",ideal:"The lens is ideal: refraction is instantaneous and there is no reflection, absorption, diffraction or chromatic dispersion.",drawing:"The curved lens outline is schematic. The rays use the thin-lens approximation at the centre plane; drawing sizes are not to scale.",infinity:"At u = f, the outgoing rays are parallel and the image is at infinity. The view shows no finite image marker or distance reading."},param:{kind:"Lens type",distance:"Object distance",focalLength:"Focal length",height:"Object height",timeStep:"Time step",duration:"Ray animation duration"},hint:{kind:"Converging lenses have positive focal length; diverging lenses have negative focal length.",distance:"Distance from the object to the centre of the lens.",focalLength:"Distance from the lens to its principal focus.",height:"Height of the object above the optical axis.",duration:"How long one animated ray takes to travel to and through the lens."},kind:{converging:"Converging (convex)",diverging:"Diverging (concave)"},preset:{distance10:"10 cm",distance20:"20 cm",distance40:"40 cm",distance60:"60 cm",focal10:"10 cm",focal20:"20 cm",focal30:"30 cm"},measure:{imageDistance:"Image distance",magnification:"Magnification",real:"Real image (1) or virtual image (0)",focalLength:"Signed focal length",imageHeight:"Image height",upright:"Upright (1) or inverted (0)",finiteImage:"Finite image (1) or at infinity (0)",power:"Lens power",rayY:"Animated ray height"},graph:{ray:"Height of the animated light ray over time"},view:{raysOption:"Show principal rays",objectsOption:"Show the object",imagesOption:"Show the image",extensionsOption:"Show virtual-ray extensions",pulsesOption:"Animate light along the rays",object:"Object",image:"Image",converging:"Converging lens",diverging:"Diverging lens",infinity:"Image at infinity \xB7 rays are parallel",real:"Real image",virtual:"Virtual image \xB7 dashed lines show where rays appear to meet",legend:"Solid lines: light rays \xB7 dashed lines: virtual extensions"},challenge:{sameSize:{title:"Make a same-size image",description:"Form a real image with the same size as the object.",hint:"For a converging lens, place the object twice as far away as the focal length."},enlarged:{title:"Enlarge a real image",description:"Form a real image at least 1.5 times larger than the object.",hint:"Use a converging lens and place the object between F and 2F."},virtual:{title:"Make an enlarged virtual image",description:"Form an upright virtual image more than 1.5 times the object's size.",hint:"Use a converging lens and move the object inside its focal length."},diverging:{title:"Try a diverging lens",description:"Make an upright, reduced virtual image with a diverging lens.",hint:"Choose the diverging lens type and trace the dashed extensions backward."},atFocus:{title:"Place the object at the focus",description:"Set the object distance equal to the focal length and observe the parallel rays.",hint:"For a converging lens, make the object distance and focal length equal."}}}},t={sim:i};export{t as default,i as sim};
